import * as THREE from 'three/webgpu';
import { texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const pos = (config && config.scenePosition) || [0, 0.7, 0];
  const rot = (config && config.sceneRotation) || [0, 0, 0];
  const scl = (config && config.sceneScale) || [1, 1, 1];
  group.position.fromArray(pos);
  group.rotation.fromArray(rot);
  group.scale.fromArray(scl);

  const baseY = pos[1];

  // Atlas source rect 512 x 320 -> aspect 1.6
  const W = 3.2;
  const H = W * (320 / 512);

  const ink = new THREE.Color('#16161d');
  const paper = new THREE.Color('#e8ecf2');
  const accentColor = new THREE.Color('#ff2a38');

  // ---- Brushed-metal surface plane ----------------------------------------
  const tex = ctx.textureLoader('/prism-assets/chrome/brushed-metal.map.png');
  if (tex) {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.anisotropy = 8;
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.ClampToEdgeWrapping;
  }

  const mat = new THREE.MeshBasicNodeMaterial({ transparent: true });
  if (tex) {
    // Tint brushed metal toward paper, slightly dimmed for ink-on-paper contrast.
    mat.colorNode = texture(tex).mul(paper).mul(0.88);
  } else {
    mat.colorNode = uniform(paper).mul(0.18).add(uniform(ink).mul(0.82));
  }
  mat.opacityNode = uniform(0.94);

  const plane = new THREE.Mesh(new THREE.PlaneGeometry(W, H), mat);
  plane.position.set(0, 0, 0);
  plane.renderOrder = 1;
  group.add(plane);

  // ---- Subtle divider line (ink, low opacity) -----------------------------
  const dividerGeom = new THREE.PlaneGeometry(W * 0.96, 0.012);
  const dividerMat = new THREE.MeshBasicNodeMaterial({
    color: ink,
    transparent: true,
    opacity: 0.32,
  });
  const divider = new THREE.Mesh(dividerGeom, dividerMat);
  divider.position.set(0, -H * 0.5 + 0.028, 0.0015);
  divider.renderOrder = 2;
  group.add(divider);

  // ---- Accent edge (signal red) — revealed on focus -----------------------
  const accentGeom = new THREE.PlaneGeometry(W * 0.992, 0.02);
  const accentMat = new THREE.MeshBasicNodeMaterial({
    color: accentColor,
    transparent: true,
    opacity: 0,
  });
  const accent = new THREE.Mesh(accentGeom, accentMat);
  accent.position.set(0, -H * 0.5 + 0.024, 0.002);
  accent.renderOrder = 3;
  group.add(accent);

  // ---- Animation registry -------------------------------------------------
  const timelines = [];
  const pushTl = (tl) => { timelines.push(tl); return tl; };
  const killAll = () => {
    while (timelines.length) timelines.pop().kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(dividerMat);
    gsap.killTweensOf(accentMat);
  };

  // ---- Handlers -----------------------------------------------------------
  group.userData.handlers = {
    hover: (over) => {
      gsap.killTweensOf(group.position);
      gsap.killTweensOf(dividerMat);
      const tl = gsap.timeline();
      if (over) {
        // rise-in (subtle): +0.15 scene units, power3.out, 0.7s
        tl.to(group.position, {
          y: baseY + 0.15,
          duration: 0.7,
          ease: 'power3.out',
        });
        tl.to(dividerMat, {
          opacity: 0.55,
          duration: 0.5,
          ease: 'power2.out',
        }, '<');
      } else {
        tl.to(group.position, {
          y: baseY,
          duration: 0.5,
          ease: 'power2.out',
        });
        tl.to(dividerMat, {
          opacity: 0.32,
          duration: 0.4,
          ease: 'power2.out',
        }, '<');
      }
      pushTl(tl);
    },

    click: () => {
      // press-down: scale 0.97, 120ms, back.out -> settle
      gsap.killTweensOf(group.scale);
      const tl = gsap.timeline();
      tl.to(group.scale, {
        x: 0.97, y: 0.97, z: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
      tl.to(group.scale, {
        x: scl[0], y: scl[1], z: scl[2],
        duration: 0.18,
        ease: 'power2.out',
      });
      pushTl(tl);

      if (ctx && typeof ctx.emit === 'function') {
        ctx.emit('hub-collection.select', {
          id: config && config.id ? config.id : 'hub-collection-row',
          source: 'list-row',
        });
      }
    },

    focus: (on) => {
      // accent edge on focus
      gsap.killTweensOf(accentMat);
      const tl = gsap.to(accentMat, {
        opacity: on ? 1 : 0,
        duration: 0.3,
        ease: 'power2.out',
      });
      pushTl(tl);
    },
  };

  // ---- Cleanup ------------------------------------------------------------
  group.userData.cleanup = () => {
    killAll();
    plane.geometry.dispose();
    mat.dispose();
    divider.geometry.dispose();
    dividerMat.dispose();
    accent.geometry.dispose();
    accentMat.dispose();
    if (tex && typeof tex.dispose === 'function') tex.dispose();
  };

  return group;
}
